3	#include "hybrid/abstract_command.hpp"
4	#include "hybrid/andes_caps.hpp"
5	#include "hybrid/dmi_poll.hpp"
6	#include "hybrid/program_buffer.hpp"
7	#include "hybrid/state_abi.h"
8	#include "hybrid/v_regfile_xfer.hpp"
9	
10	#include <array>
11	#include <cstdint>
12	#include <optional>
13	#include <stdexcept>
14	#include <string>
15	
16	namespace hybrid {
17	
18	struct DmiBus
19	{
20	  virtual ~DmiBus() = default;
21	  virtual void write(uint8_t reg, uint32_t value) = 0;
22	  virtual auto read(uint8_t reg) -> uint32_t = 0;
23	};
24	
25	inline auto read_register_64(DmiBus& bus, uint16_t regno,
26	                             const char* poll_label) -> uint64_t;
27	
28	class ResumeDriver
29	{
30	public:
31	  // data0/data1/abstractcs/command are defined once in abstract_command.hpp;
32	  // dmcontrol/dmstatus are run-control registers specific to this driver.
33	  static constexpr uint8_t kData0      = kDmiData0;
34	  static constexpr uint8_t kData1      = kDmiData1;
35	  static constexpr uint8_t kDmcontrol  = 0x10;
36	  static constexpr uint8_t kDmstatus   = 0x11;
37	  static constexpr uint8_t kAbstractcs = kDmiAbstractcs;
38	  static constexpr uint8_t kCommand    = kDmiCommand;
39	
40	  static constexpr uint16_t kCsrDpc      = 0x7B1;
41	  static constexpr uint16_t kCsrDcsr     = 0x7B0;
42	  static constexpr uint16_t kCsrPmpcfg0  = 0x3A0;
43	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
44	  static constexpr uint16_t kCsrFcsr     = 0x003;
45	  static constexpr uint16_t kCsrMstatus  = 0x300;
46	  static constexpr uint16_t kCsrMisa     = 0x301;
47	  static constexpr uint16_t kCsrMedeleg  = 0x302;
48	  static constexpr uint16_t kCsrMideleg  = 0x303;
49	  static constexpr uint16_t kCsrMie      = 0x304;
50	  static constexpr uint16_t kCsrMtvec    = 0x305;
51	  static constexpr uint16_t kCsrMscratch = 0x340;
52	  static constexpr uint16_t kCsrMepc     = 0x341;
53	  static constexpr uint16_t kCsrMcause   = 0x342;
54	  static constexpr uint16_t kCsrMtval    = 0x343;
55	  static constexpr uint16_t kCsrMip      = 0x344;
56	  static constexpr uint16_t kCsrSatp     = 0x180;
57	  static constexpr uint16_t kCsrMcycle   = 0xB00;
58	  static constexpr uint16_t kCsrMinstret = 0xB02;
59	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
60	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
61	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
62	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
63	  static constexpr uint16_t kCsrVlenb    = 0xC22;
64	  static constexpr uint16_t kCsrVstart   = 0x008;
65	  static constexpr uint16_t kCsrVxsat    = 0x009;
66	  static constexpr uint16_t kCsrVxrm     = 0x00A;
67	  static constexpr uint16_t kCsrVcsr     = 0x00F;
68	  static constexpr uint16_t kCsrVtype    = 0xC21;
69	  static constexpr uint16_t kCsrVl       = 0xC20;
70	
71	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
72	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
73	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
74	
75	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
76	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
77	
78	  static constexpr uint32_t kAbstractcsBusy        = hybrid::kAbstractcsBusy;
79	  static constexpr uint32_t kAbstractcsCmderrMask  = hybrid::kAbstractcsCmderrMask;
80	
81	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
82	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
83	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
84	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
85	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
86	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
87	
88	  static constexpr unsigned kPollIterations = kDmiPollIterations;
89	
90	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
91	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
92	  // "unset" sentinel; a non-V resume never reads it, but a V resume with the
93	  // GPA still unset throws in the sweep (no silent transport via a bogus
94	  // address). The simulator passes the real value from platform.main_memory.
95	  // caps: which Andes custom CSRs the TARGET core implements (derived from its
96	  // config.inc, supplied by the sim binary). Defaults to all() -- transport
97	  // every CSR, the prior behavior -- so existing call sites are unchanged.
98	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
99	                        AndesCaps caps = AndesCaps::all())
100	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
101	  {}
102	
103	  void resume(const hybrid_state_v1& state)
104	  {
105	    if (state.magic != HYBRID_STATE_MAGIC)
106	      throw std::runtime_error("ResumeDriver::resume: bad magic");
107	    if (state.version != HYBRID_STATE_VERSION)
108	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
109	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
110	    if (state.priv == 2 || state.priv > 3)
111	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
112	
113	    // dmactive must transition 0->1 in its own write before any other
114	    // DMCONTROL bit is honored (RISC-V Debug Spec).
115	    bus_.write(kDmcontrol, kDmcontrolDmactive);
116	    request_halt();
117	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
118	
119	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
120	    // accepted (FS or VS == Off disables the extension and the hart NACKs
121	    // the writes). The drained state.mstatus may legitimately carry FS or
122	    // VS at Off (e.g. an OS context-switched the regs away before the
123	    // trigger fired) -- gating the write on the drained field skips the
124	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
125	    // write mstatus when either extension is in scope; force-OR Initial
126	    // when the drained field is Off. This enable is local to the vsim
127	    // phase; the state.mstatus written to the handoff file is left
128	    // unmodified.
129	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
130	      uint64_t enable_mstatus = state.mstatus;
131	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
132	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
133	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
134	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
135	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
136	    }
137	
138	    // FPR restore (requires mstatus.FS enabled above).
139	    if (state.flags & HYBRID_FLAG_FP) {
140	      for (uint16_t i = 0; i < 32; ++i)
141	        write_64bit_register(regno_fpr(i), state.fpr[i]);
142	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
143	      // fallback scratch x5 is overwritten by the GPR loop below.
144	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
145	    }
146	
147	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
148	    // the GPR loop overwrites x5 afterward so state is preserved).
149	    if (state.flags & HYBRID_FLAG_V) {
150	      // V data regfile: reload v0..v31 from the shared scratch region via the
151	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
152	      // because the sweep's own vsetvl (e8/m1) clobbers vtype/vl/vstart, which
153	      // the restore then overwrites with the architectural values. The sweep
154	      // uses x5/x6/x7 as scratch (x7 is the base pointer); the GPR loop below
155	      // restores all three. The wire format reserves HYBRID_VLEN_BYTES_MAX per
156	      // register, so that -- not the runtime vlenb -- is the scratch stride.
157	      if (scratch_gpa_ == kVScratchGpaUnset)
158	        throw std::runtime_error(
159	          "ResumeDriver::resume: V state present but scratch GPA unset");
160	      pb_v_data_sweep(bus_, scratch_gpa_, HYBRID_VLEN_BYTES_MAX, state.vlenb,
161	                      /*load=*/true);
162	
163	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
164	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
165	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
166	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
167	      write_64bit_register(regno_gpr(5), state.vl);
168	      write_64bit_register(regno_gpr(6), state.vtype);
169	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
170	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
171	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
172	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
173	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
174	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
175	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
176	    }
177	
178	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
179	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
180	    // in the drained privilege; M-mode states skip the write (prv already 3).
181	    // Before the GPR loop: a PB fallback would clobber scratch x5.
182	    if (state.priv != 3) {
183	      // L2 slice: with PMP implemented and no matching entry, every S/U
184	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
185	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
186	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
187	      // RV64. Tolerant writes: entries beyond what the hart implements
188	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
189	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
190	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
191	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
192	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
193	
194	      const uint64_t dcsr =
195	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
196	      write_csr_abstract_or_pb(kCsrDcsr,
197	                               (dcsr & ~uint64_t{0x3}) | state.priv);
198	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
199	      // silently measure the ROI in the wrong privilege. Verify and abort.
200	      const uint64_t got =
201	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
202	        & 0x3u;
203	      if (got != state.priv)
204	        throw std::runtime_error(
205	          "ResumeDriver::resume: engine does not implement privilege level "
206	          + std::to_string(state.priv)
207	          + " (dcsr.prv pinned to " + std::to_string(got)
208	          + "); pick an S/U-capable engine");
209	    }
210	
211	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite).
212	    for (uint16_t i = 1; i < 32; ++i)
213	      write_64bit_register(regno_gpr(i), state.gpr[i]);
214	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
215	
216	    write_csr_tolerant(kCsrMtvec, state.mtvec);
217	
218	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
219	    // register with no hardware side effects, legal to use inside a trap-free
220	    // ROI. Restore it so a value stashed before the handoff survives into the
221	    // vsim phase.
222	    write_csr_tolerant(kCsrMscratch, state.mscratch);
223	
224	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
225	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
226	    // value stashed before the handoff must survive into the vsim phase (same
227	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
228	    // hardware-driven pending bits, or mtval on a core that hardwires it)
229	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
230	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
231	    write_csr_tolerant(kCsrMepc,   state.mepc);
232	    write_csr_tolerant(kCsrMcause, state.mcause);
233	    write_csr_tolerant(kCsrMtval,  state.mtval);
234	    write_csr_tolerant(kCsrMie,    state.mie);
235	    write_csr_tolerant(kCsrMip,    state.mip);
236	
237	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
238	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
239	    // caches) but has no cache model, so without this the cycle engine resumes
240	    // at the ROI with caches at their reset default -- DISABLED -- and the
241	    // whole measured window runs uncached, inflating it severalfold. Tolerant
242	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
243	    // write as a no-op, and a drained 0 (caches were off) restores the reset
244	    // state, so this is always safe to issue.
245	    write_csr_tolerant(kCsrMcacheCtl, state.mcache_ctl);
246	    write_csr_tolerant(kCsrMmiscCtl,  state.mmisc_ctl);
247	
248	    // Andes V5 CSR block (v3): the boot-static memory-system / extension CSRs
249	    // the functional engine set up before the ROI -- PMA attributes, mxstatus,
250	    // ILM/DLM bases, perf throttling, stack-protection bounds, the CoDense/Zcmt
251	    // table bases -- plus the DSP overflow flag (ucode). Same rationale as
252	    // mcache_ctl: without them the cycle engine resumes with the wrong memory
253	    // system or faults on the first CoDense/DSP op in the window. caps_ gates
254	    // each write to the CSRs the TARGET core actually implements (from its
255	    // config.inc): restoring an absent custom CSR is NOT a clean no-op -- the
256	    // abstract write stalls the DM handshake (observed: ucode without DSP,
257	    // mecc_code without ECC). HYBRID_ANDES_CSR_LIST is the single source of
258	    // truth shared with the plugin drain, StateDrain, and state_diff.
259	    if (state.flags & HYBRID_FLAG_ANDES) {
260	#define X(field, addr, name) \
261	  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.andes.field);
262	      HYBRID_ANDES_CSR_LIST(X)
263	#undef X
264	      // PMA: every pmaaddr before any pmacfg (a TOR/NAPOT cfg consumes the addr
265	      // already in place -- mirror the PMP ordering). On RV64 only even pmacfg
266	      // CSRs exist, so slot i maps to 0xBC0 + 2*i; pmaaddr i maps to 0xBD0 + i.
267	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
268	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
269	          write_csr_tolerant(HYBRID_PMA_ADDR0_CSR + i, state.andes.pmaaddr[i]);
270	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
271	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
272	          write_csr_tolerant(HYBRID_PMA_CFG0_CSR + 2 * i, state.andes.pmacfg[i]);
273	    }
274	
275	    // M-ext CSR block (v4): the writable M-mode CSRs across the whole SPA, each
276	    // capability-gated by address exactly like the Andes block above. caps_
277	    // skips any the target core lacks (most on an M-only core), so the absent
278	    // ones never stall the DM. Same single-source X-macro shared with the plugin
279	    // drain, StateDrain, and state_diff.
280	    if (state.flags & HYBRID_FLAG_M_EXT) {
281	#define X(field, addr, name) \
282	  if (caps_.supports_csr(addr)) write_csr_tolerant(addr, state.m_ext.field);
283	      HYBRID_M_EXT_CSR_LIST(X)
284	#undef X
285	    }
286	
287	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
288	    // from QEMU1's drain value. Without this, vsim's local counter starts
289	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
290	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
291	    // overwrite here as the GPR loop already ran.
292	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
293	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
294	
295	    clear_cmderr_if_set();
296	    request_resume();
297	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
298	                   "ResumeDriver resume");
299	  }
300	
301	private:
302	  void request_halt()
303	  {
304	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
305	  }
306	
307	  void request_resume()
308	  {
309	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
310	  }
311	
312	  void write_64bit_register(uint16_t regno, uint64_t value)
313	  {
314	    write_register_abstract(bus_, regno, value);
315	  }
316	
317	  // Abstract-first CSR write with Program Buffer fallback.
318	  // Tries an abstract register write; if the DM signals cmderr, clears it,
319	  // stages the value in scratch_gpr via abstract GPR write, then executes a
320	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
321	  // to x5 (t0) which the GPR restore loop overwrites later.
322	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
323	                                 uint8_t scratch_gpr = 5)
324	  {
325	    write_64bit_register(regno_csr(csr), value);
326	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
327	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
328	    write_64bit_register(regno_gpr(scratch_gpr), value);
329	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
330	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
331	  }
332	
333	  // Write a CSR-addressable register and clear any cmderr the DM raised.
334	  // Used for CSRs whose abstract-access support may be implementation
335	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
336	  // remaining writes.
337	  void write_csr_tolerant(uint16_t csr, uint64_t value)
338	  {
339	    write_64bit_register(regno_csr(csr), value);
340	    clear_cmderr_if_set();
341	  }
342	
343	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
344	  // is rejected until the bits are W1C-cleared. We tolerate per-register
345	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
346	  // error before resuming so the hart isn't left in a stuck state.
347	  // B17: record the last observed non-zero cmderr and a clear count so a
348	  // partially-broken restore is observable via the public accessors
349	  // instead of silently swallowed.
350	  void clear_cmderr_if_set()
351	  {
352	    const auto status = bus_.read(kAbstractcs);
353	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
354	    if (code != 0u) {
355	      last_observed_cmderr_ = code;
356	      ++cmderr_clear_count_;
357	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
358	    }
359	  }
360	
361	  DmiBus& bus_;
362	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
363	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
364	  uint32_t last_observed_cmderr_ = 0;
365	  uint64_t cmderr_clear_count_   = 0;
366	
367	public:
368	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
369	  // at least one abstract write tripped a sticky cmderr the restore
370	  // tolerated by clearing. cmderr_clear_count() is the total number of
371	  // such clears across all calls into clear_cmderr_if_set() this run.
372	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
373	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
374	};
375	
376	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
377	// via an Abstract Command. Halts-and-reads contract: caller must have the
378	// hart in the halted state. Shared by StateDrain (drain at exit). If
379	// abstractcs.cmderr goes sticky after the command, the helper clears it and
380	// reports 0 rather than blocking the caller -- a missing CSR mirrors as zero
381	// instead of corrupting the adjacent field.
382	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
383	                                     const char* poll_label
384	                                       = "read_register_64")
385	  -> std::optional<uint64_t>
386	{
387	  using RD = ResumeDriver;
388	  bus.write(RD::kCommand,
389	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
390	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
391	  const auto status = bus.read(RD::kAbstractcs);
392	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
393	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
394	    return std::nullopt;
395	  }
396	  const uint64_t lo = bus.read(RD::kData0);
397	  const uint64_t hi = bus.read(RD::kData1);
398	  return lo | (hi << 32);
399	}
400	
401	inline auto read_register_64(DmiBus& bus, uint16_t regno,
402	                             const char* poll_label = "read_register_64")
403	  -> uint64_t
404	{
405	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
406	}
407	
408	}  // namespace hybrid
